using System;
using System.IO;
using System.Linq;
using UnityEngine;
using BlackStartX.GestureManager;
using BlackStartX.GestureManager.Editor.Modules.Vrc3;
public static class Stage4Capacity
{
    static ModuleVrc3 Module(){return UnityEngine.Object.FindObjectsOfType<GestureManager>().Select(g=>g.Module as ModuleVrc3).First(m=>m!=null&&m.Avatar.GetComponentsInChildren<Transform>(true).Any(t=>t.name=="MorphForgeGeometry"));}
    static ParticleSystem Store(ModuleVrc3 m){return m.Avatar.GetComponentsInChildren<ParticleSystem>(true).First(p=>p.name=="Store");}
    public static string Preload(){var m=Module();var ps=Store(m);var p=new ParticleSystem.Particle[16384];for(int i=0;i<p.Length;i++){p[i].position=new Vector3((80+i%32*3+.5f-128)*.25f,(i/1024*3+.5f-128)*.25f,(80+i/32%32*3+.5f-128)*.25f);p[i].startSize3D=Vector3.one*.25f;p[i].startLifetime=1000000;p[i].remainingLifetime=1000000;p[i].startColor=new Color32(4,0,0,0);p[i].randomSeed=(uint)i+1;}ps.SetParticles(p,p.Length);return Inspect();}
    public static string Inspect(){var m=Module();var ps=Store(m);var p=new ParticleSystem.Particle[ps.main.maxParticles];int n=ps.GetParticles(p);var indices=new System.Collections.Generic.HashSet<int>();int malformed=0;for(int i=0;i<n;i++){var q=p[i].position/.25f+Vector3.one*128-Vector3.one*.5f;int x=Mathf.RoundToInt((q.x-80)/3),y=Mathf.RoundToInt(q.y/3),z=Mathf.RoundToInt((q.z-80)/3);var ideal=new Vector3(80+x*3,y*3,80+z*3);if(x<0||x>=32||y<0||y>=16||z<0||z>=32||Vector3.Distance(q,ideal)>.001f||Vector3.Distance(p[i].startSize3D,Vector3.one*.25f)>.001f)malformed++;else indices.Add(x+z*32+y*1024);}
    int sent=0;if(File.Exists("Docs/Stage4/capacity-progress.json"))sent=Mathf.Clamp((int)Newtonsoft.Json.Linq.JObject.Parse(File.ReadAllText("Docs/Stage4/capacity-progress.json"))["sent"]-4,0,16384);var holes=Enumerable.Range(0,sent).Where(i=>!indices.Contains(i)).ToArray();int patchStart=File.Exists("Docs/Stage4/pump-runtime-patch.json")?(int)Newtonsoft.Json.Linq.JObject.Parse(File.ReadAllText("Docs/Stage4/pump-runtime-patch.json"))["firstGuaranteedPatchedIndex"]:16384;var v=new{patchStart,missingAfterPatch=holes.Count(i=>i>=patchStart),missingAfterPatchSample=holes.Where(i=>i>=patchStart).Take(64).ToArray(),inferredSent=sent,missingInCompletedPrefix=holes.Length,missingSample=holes.Take(64).ToArray(),count=n,isPlaying=ps.isPlaying,isPaused=ps.isPaused,isStopped=ps.isStopped,systemTime=ps.time,finiteLifetimes=p.Take(n).Count(x=>!float.IsInfinity(x.remainingLifetime)),capacity=ps.main.maxParticles,unique=indices.Count,malformed,missing=16384-indices.Count,received=m.GetParam("MF3_RxCount").FloatValue(),completed=m.GetParam("MF3_DoneCount").FloatValue(),busy=m.GetParam("MF3_Busy").BoolValue(),inbox=m.GetParam("MF3_InboxReady").BoolValue(),frame=Time.frameCount,frameSeconds=Time.unscaledDeltaTime,allocatedBytes=UnityEngine.Profiling.Profiler.GetTotalAllocatedMemoryLong(),scope="Editor native particle storage; prefill is NOT OSC evidence"};return Newtonsoft.Json.JsonConvert.SerializeObject(v);}
 public static string ApplyPumpLifetimeFix(){var m=Module();var pump=m.Avatar.GetComponentsInChildren<ParticleSystem>(true).First(p=>p.name=="Pump"&&p.transform.parent.name=="Center");var before=Inspect();var main=pump.main;float old=main.startLifetime.constant;main.startLifetime=.5f;var marker=new{time=DateTime.UtcNow.ToString("O"),oldLifetime=old,newLifetime=.5f,firstGuaranteedPatchedIndex=(int)Newtonsoft.Json.Linq.JObject.Parse(File.ReadAllText("Docs/Stage4/capacity-progress.json"))["sent"]+128,before=Newtonsoft.Json.Linq.JObject.Parse(before),scope="Temporary Play Mode patch; final prefab will receive same .5s lifetime via builder"};var json=Newtonsoft.Json.JsonConvert.SerializeObject(marker,Newtonsoft.Json.Formatting.Indented);File.WriteAllText("Docs/Stage4/pump-runtime-patch.json",json);return json;}
 public static async System.Threading.Tasks.Task<string> FrameSample(){var ps=Store(Module());var times=new System.Collections.Generic.List<double>();int last=-1;double end=Time.realtimeSinceStartupAsDouble+3;while(Time.realtimeSinceStartupAsDouble<end){await System.Threading.Tasks.Task.Delay(5);if(Time.frameCount!=last){last=Time.frameCount;times.Add(Time.unscaledDeltaTime*1000.0);}}times.Sort();var report=new{count=ps.particleCount,samples=times.Count,p50Ms=times[(int)((times.Count-1)*.5)],p95Ms=times[(int)((times.Count-1)*.95)],maxMs=times.Last(),visible=ps.GetComponent<Renderer>().isVisible,allocatedBytes=UnityEngine.Profiling.Profiler.GetTotalAllocatedMemoryLong(),scope="Editor real frame durations, not isolated VRChat client GPU benchmark"};return Newtonsoft.Json.JsonConvert.SerializeObject(report);}
 public static string CompleteReport(){
  var m=Module();var ps=Store(m);var values=new ParticleSystem.Particle[ps.main.maxParticles];int n=ps.GetParticles(values);var indices=new System.Collections.Generic.HashSet<int>();int malformed=0,metadataMismatch=0;for(int i=0;i<n;i++){var q=values[i].position/.25f+Vector3.one*128-Vector3.one*.5f;int x=Mathf.RoundToInt((q.x-80)/3),y=Mathf.RoundToInt(q.y/3),z=Mathf.RoundToInt((q.z-80)/3);if(x<0||x>=32||y<0||y>=16||z<0||z>=32||Vector3.Distance(q,new Vector3(80+x*3,y*3,80+z*3))>.001f||Vector3.Distance(values[i].startSize3D,Vector3.one*.25f)>.001f)malformed++;else indices.Add(x+z*32+y*1024);var c=values[i].startColor;if(Mathf.RoundToInt(c.r*63f/255)!=1||c.g!=0||c.b!=0||c.a!=0)metadataMismatch++;}
  var missing=Enumerable.Range(0,16384).Where(j=>!indices.Contains(j)).ToArray();var commands=missing.Select(j=>new{op="voxel",min=new[]{80+j%32*3,j/1024*3,80+j/32%32*3}}).ToArray();File.WriteAllText("Docs/Stage4/capacity-missing-commands.json",Newtonsoft.Json.JsonConvert.SerializeObject(commands));
  byte[] blob;using(var ms=new MemoryStream()){using(var w=new BinaryWriter(ms)){w.Write(n);for(int j=0;j<n;j++){var a=values[j];foreach(var v in new[]{a.position.x,a.position.y,a.position.z,a.startSize3D.x,a.startSize3D.y,a.startSize3D.z})w.Write(v);w.Write(a.startColor.r);w.Write(a.startColor.g);w.Write(a.startColor.b);w.Write(a.startColor.a);}}blob=ms.ToArray();}File.WriteAllBytes("Docs/Stage4/capacity-particles.bin",blob);string hash;using(var sha=System.Security.Cryptography.SHA256.Create())hash=BitConverter.ToString(sha.ComputeHash(blob)).Replace("-","");
  var progress=Newtonsoft.Json.Linq.JObject.Parse(File.ReadAllText("Docs/Stage4/capacity-progress.json"));var report=new{time=DateTime.UtcNow.ToString("O"),success=n==16384&&indices.Count==16384&&malformed==0&&metadataMismatch==0,count=n,unique=indices.Count,malformed,metadataMismatch,missing,received=m.GetParam("MF3_RxCount").FloatValue(),completed=m.GetParam("MF3_DoneCount").FloatValue(),lastRxSeq=m.GetParam("MF3_LastRxSeq").IntValue(),busy=m.GetParam("MF3_Busy").BoolValue(),inbox=m.GetParam("MF3_InboxReady").BoolValue(),progress,nativeSnapshotSha256=hash,nativeSnapshot="Docs/Stage4/capacity-particles.bin",scope="Actual native particles after UDP; no particle prefill in this run"};var json=Newtonsoft.Json.JsonConvert.SerializeObject(report,Newtonsoft.Json.Formatting.Indented);File.WriteAllText("Docs/Stage4/capacity-native-current.json",json);return json;
 }
}
